INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(45261, 'Lamentations 3:34', 'Lamentations', 3, 34, 'کله چې په مُلک کښې ټول قېديان د پښو لاندې چخڼى کړى،', 'کله چې په ملک کشې تول قېدیان د پشو لاندې چخنی کری،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_34.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45262, 'Lamentations 3:35', 'Lamentations', 3, 35, 'او کله چې يو انسان د خُدائ تعالىٰ په وړاندې د بل چا حق په زور وهى،', 'او کله چې یو انسان د خدای تعالی په وراندې د بل چا حق په زور وهی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_35.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45263, 'Lamentations 3:36', 'Lamentations', 3, 36, 'کله چې يو سړے په عدالت کښې څوک د اِنصاف نه محروموى، ولې مالِک داسې ظلم نۀ ګورى؟', 'کله چې یو سرے په عدالت کشې چوک د انصاف نه محروموی، ولې مالک داسې ظلم نۀ ګوری؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_36.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45264, 'Lamentations 3:37', 'Lamentations', 3, 37, 'څوک په خپل حکم څۀ کار کولے شى ترڅو چې مالِک په خپله د هغې حکم نۀ وى کړے؟', 'چوک په خپل حکم چۀ کار کولے شی ترچو چې مالک په خپله د هغې حکم نۀ وی کرے؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_37.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45265, 'Lamentations 3:38', 'Lamentations', 3, 38, 'ولې د خُدائ تعالىٰ د خوا نه ښۀ او بد دواړه نۀ راځى؟', 'ولې د خدای تعالی د خوا نه شۀ او بد دواره نۀ راجی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_38.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45266, 'Lamentations 3:39', 'Lamentations', 3, 39, 'نو بيا ژوندے انسان ولې شکايت کوى کله چې ورته د خپلو ګناهونو سزا مِلاو شى.', 'نو بیا ژوندے انسان ولې شکایت کوی کله چې ورته د خپلو ګناهونو سزا ملاو شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_39.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45267, 'Lamentations 3:40', 'Lamentations', 3, 40, 'راځئ چې مونږ خپلې طريقې وآزمايو او مالِک خُدائ ته واپس راوګرځُو.', 'راجی چې مونز خپلې طریقې وازمایو او مالک خدای ته واپس راوګرجو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_40.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45268, 'Lamentations 3:41', 'Lamentations', 3, 41, 'راځئ چې په اخلاص خپل لاسونه پورته کړُو او آسمانى خُدائ پاک ته داسې ووايو،', 'راجی چې په اخلاص خپل لاسونه پورته کرو او اسمانی خدای پاک ته داسې ووایو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_41.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45269, 'Lamentations 3:42', 'Lamentations', 3, 42, '”مونږ ګناه او سرکشى وکړه او تا مونږ معاف کړى نۀ يُو.', '”مونز ګناه او سرکشی وکره او تا مونز معاف کری نۀ یو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_42.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45270, 'Lamentations 3:43', 'Lamentations', 3, 43, 'تا خپلې د قهر جامې واغوستلې او مونږ پسې شوې او په بې‌رحمۍ سره دې مونږ مړۀ کړُو.', 'تا خپلې د قهر جامې واغوستلې او مونز پسې شوې او په بې‌رحمی سره دې مونز مرۀ کرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_43.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45271, 'Lamentations 3:44', 'Lamentations', 3, 44, 'تا خپل ځان په وريځ کښې ونغښتلو ترڅو هيڅ دُعا هم تا ته در ونۀ رسيږى.', 'تا خپل جان په وریج کشې ونغشتلو ترچو هیچ دعا هم تا ته در ونۀ رسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_44.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45272, 'Lamentations 3:45', 'Lamentations', 3, 45, 'تا مونږ پليت کړُو او د قومونو په مينځ کښې دې رانه د ګند ډېرے جوړ کړُو.', 'تا مونز پلیت کرو او د قومونو په مینج کشې دې رانه د ګند دېرے جور کرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_45.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45273, 'Lamentations 3:46', 'Lamentations', 3, 46, 'زمونږ ټولو دشمنانو زمونږ خلاف خپلې خولې وازې کړې.', 'زمونز تولو دشمنانو زمونز خلاف خپلې خولې وازې کرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_46.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45274, 'Lamentations 3:47', 'Lamentations', 3, 47, 'يرې واخستُو او په کنده کښې وغورزېدُو. تباهى او بربادى راباندې راغله.', 'یرې واخستو او په کنده کشې وغورزېدو. تباهی او بربادی راباندې راغله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_47.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45275, 'Lamentations 3:48', 'Lamentations', 3, 48, 'زما د خلقو د تباهۍ په وجه زما د سترګو نه د اوښکو سيندونه بهيږى.', 'زما د خلقو د تباهی په وجه زما د سترګو نه د اوشکو سیندونه بهیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_48.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45276, 'Lamentations 3:49', 'Lamentations', 3, 49, 'زما سترګو نه به اوښکې جارى وى بې له آرام کولو نه،', 'زما سترګو نه به اوشکې جاری وی بې له ارام کولو نه،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_49.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45277, 'Lamentations 3:50', 'Lamentations', 3, 50, 'ترڅو چې مالِک خُدائ پاس د آسمان نه نظر واچوى او دا حال وګورى.', 'ترچو چې مالک خدای پاس د اسمان نه نظر واچوی او دا حال وګوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_50.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45278, 'Lamentations 3:51', 'Lamentations', 3, 51, 'چې کله زۀ په ښار کښې د ټولو ښځو حالت ګورم نو زما زړۀ غمژن شى.', 'چې کله زۀ په شار کشې د تولو شجو حالت ګورم نو زما زرۀ غمژن شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_51.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45279, 'Lamentations 3:52', 'Lamentations', 3, 52, 'هغوئ څوک چې هيڅ بې‌هيڅه زما دشمنان وُو هغوئ لکه د مرغۍ په شان زۀ وويشتم.', 'هغوی چوک چې هیچ بې‌هیچه زما دشمنان وو هغوی لکه د مرغی په شان زۀ وویشتم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_52.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45280, 'Lamentations 3:53', 'Lamentations', 3, 53, 'هغوئ زۀ ژوندے په کنده کښې ورواچولم او په ما يې کاڼى راوويشتل.', 'هغوی زۀ ژوندے په کنده کشې ورواچولم او په ما یې کانی راوویشتل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_53.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45281, 'Lamentations 3:54', 'Lamentations', 3, 54, 'اوبۀ زما تر سره راورسېدلې او وئيل مې چې ډوبېږم.', 'اوبۀ زما تر سره راورسېدلې او وییل مې چې دوبېزم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_54.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45282, 'Lamentations 3:55', 'Lamentations', 3, 55, 'اے مالِکه خُدايه، ما د کندې د بېخ نه ستا په نامه مِنت زارى وکړه.', 'اے مالکه خدایه، ما د کندې د بېخ نه ستا په نامه منت زاری وکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_55.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45283, 'Lamentations 3:56', 'Lamentations', 3, 56, 'تا زما خواست اورېدلے دے، خپل غوږونه مۀ بندوه، د مدد دپاره زما آواز واوره.', 'تا زما خواست اورېدلے دے، خپل غوزونه مۀ بندوه، د مدد دپاره زما اواز واوره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_56.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45284, 'Lamentations 3:57', 'Lamentations', 3, 57, 'تۀ ما ته رانزدې شوې کله چې ما درته آواز وکړو، تا ما ته وفرمائيل چې يرېږه مه.', 'تۀ ما ته رانزدې شوې کله چې ما درته اواز وکرو، تا ما ته وفرماییل چې یرېزه مه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_57.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45285, 'Lamentations 3:58', 'Lamentations', 3, 58, 'اے مالِکه، تا زما مسئله راوچته کړه او تا زما ژوند بچ کړو.', 'اے مالکه، تا زما مسیله راوچته کره او تا زما ژوند بچ کرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_58.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45286, 'Lamentations 3:59', 'Lamentations', 3, 59, 'اے مالِکه خُدايه، کوم بد چې ما سره وشُو تا هغه وليدل، زما د مسئلې اِنصاف وکړه.', 'اے مالکه خدایه، کوم بد چې ما سره وشو تا هغه ولیدل، زما د مسیلې انصاف وکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_59.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45287, 'Lamentations 3:60', 'Lamentations', 3, 60, 'تا د هغوئ د انتقام ټول اور وليدو، د هغوئ ټولې منصوبې زما خلاف دى.', 'تا د هغوی د انتقام تول اور ولیدو، د هغوی تولې منصوبې زما خلاف دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_60.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45288, 'Lamentations 3:61', 'Lamentations', 3, 61, 'اے مالِکه خُدايه، تا د هغوئ ټول پيغورونه واورېدل، د هغوئ ټولې منصوبې چې زما خلاف دى.', 'اے مالکه خدایه، تا د هغوی تول پیغورونه واورېدل، د هغوی تولې منصوبې چې زما خلاف دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_61.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45289, 'Lamentations 3:62', 'Lamentations', 3, 62, 'زما مخالفين ټوله ورځ زما خلاف پس پس او ګنګوسى کوى.', 'زما مخالفین توله ورج زما خلاف پس پس او ګنګوسی کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_62.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45290, 'Lamentations 3:63', 'Lamentations', 3, 63, 'هغوئ ته وګوره، سحر نه تر ماښامه پورې، زۀ د هغوئ د پيغورونو په سندرو کښې نمونه يم.', 'هغوی ته وګوره، سحر نه تر ماشامه پورې، زۀ د هغوی د پیغورونو په سندرو کشې نمونه یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_63.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45291, 'Lamentations 3:64', 'Lamentations', 3, 64, 'اے مالِکه خُدايه، هغوئ ته بدله ورکړه، هغوئ ته د خپل عمل په مطابق بدله ورکړه.', 'اے مالکه خدایه، هغوی ته بدله ورکره، هغوی ته د خپل عمل په مطابق بدله ورکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_64.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45292, 'Lamentations 3:65', 'Lamentations', 3, 65, 'هغوئ په زړونو غمژن کړه او ستا لعنت دې په هغوئ باندې وى.', 'هغوی په زرونو غمژن کره او ستا لعنت دې په هغوی باندې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_65.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45293, 'Lamentations 3:66', 'Lamentations', 3, 66, 'هغوئ په خپله غصه کښې راونيسه، مالِکه خُدايه، د زمکې د مخ نه يې جارُو کړه.“', 'هغوی په خپله غصه کشې راونیسه، مالکه خدایه، د زمکې د مخ نه یې جارو کره.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Lamentations_3_66.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
